     1	package br.com.loja.pedidos.shipping;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	import br.com.loja.pedidos.common.DomainException;
     7	import br.com.loja.pedidos.common.Money;
     8	
     9	/** Entrega cotada na TransLog; cada serviço dela (STD, EXP) vira uma opção nossa. */
    10	public class TransLogShipping implements ShippingOption {
    11	
    12	    private final String code;
    13	    private final String service;
    14	    private final TransLogClient client;
    15	
    16	    public TransLogShipping(String code, String service, TransLogClient client) {
    17	        this.code = code;
    18	        this.service = service;
    19	        this.client = client;
    20	    }
    21	
    22	    @Override
    23	    public String code() {
    24	        return code;
    25	    }
    26	
    27	    @Override
    28	    public ShippingQuote quote(ShippingRequest request) {
    29	        long grams = request.weightKg().movePointRight(3).setScale(0, RoundingMode.CEILING).longValueExact();
    30	        TransLogClient.TransLogQuote quote = client.quote(request.zipCode(), grams, service)
    31	                .orElseThrow(() -> DomainException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
    32	        BigDecimal cost = Money.round(BigDecimal.valueOf(quote.priceCents(), 2));
    33	        int days = Math.ceilDiv(quote.etaHours(), 24) + request.region().carrierExtraDays();
    34	        return new ShippingQuote(cost, days);
    35	    }
    36	}
