=== payment/CreditCardPayment.java
     1	package br.com.loja.pedidos.payment;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     5	import java.math.RoundingMode;
     6	
     7	import org.springframework.stereotype.Component;
     8	
     9	import br.com.loja.pedidos.common.Money;
    10	
    11	@Component
    12	public class CreditCardPayment implements PaymentMethod {
    13	
    14	    private static final int MAX_INSTALLMENTS = 12;
    15	    private static final int MAX_INTEREST_FREE_INSTALLMENTS = 3;
    16	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    17	
    18	    @Override
    19	    public String code() {
    20	        return "CREDIT_CARD";
    21	    }
    22	
    23	    @Override
    24	    public boolean allowsInstallments(int installments) {
    25	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
    26	    }
    27	
    28	    @Override
    29	    public PaymentCharge charge(PaymentContext context) {
    30	        BigDecimal total = context.orderTotal();
    31	        int n = context.installments();
    32	        if (n <= MAX_INTEREST_FREE_INSTALLMENTS) {
    33	            BigDecimal installment = Money.round(total.divide(BigDecimal.valueOf(n), 10, RoundingMode.HALF_EVEN));
    34	            return new PaymentCharge(total, installment);
    35	        }
    36	        // tabela Price: parcela = total * i / (1 - (1 + i)^-n)
    37	        MathContext mc = MathContext.DECIMAL128;
    38	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, mc);
    39	        BigDecimal discountFactor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, mc), mc);
    40	        BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE, mc).divide(discountFactor, mc));
    41	        return new PaymentCharge(installment.multiply(BigDecimal.valueOf(n)), installment);
    42	    }
    43	}
