     1	package br.com.loja.pedidos.shipping;
     2	
     3	import java.net.URI;
     4	import java.net.URLEncoder;
     5	import java.net.http.HttpClient;
     6	import java.net.http.HttpRequest;
     7	import java.net.http.HttpResponse;
     8	import java.nio.charset.StandardCharsets;
     9	import java.time.Duration;
    10	import java.util.Optional;
    11	import java.util.concurrent.CompletableFuture;
    12	import java.util.concurrent.TimeUnit;
    13	
    14	import org.springframework.beans.factory.annotation.Value;
    15	import org.springframework.http.HttpStatus;
    16	import org.springframework.stereotype.Component;
    17	
    18	import br.com.loja.pedidos.common.DomainException;
    19	import tools.jackson.databind.JsonNode;
    20	import tools.jackson.databind.json.JsonMapper;
    21	
    22	@Component
    23	public class HttpTransLogClient implements TransLogClient {
    24	
    25	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
    26	
    27	    private final String baseUrl;
    28	    private final JsonMapper mapper;
    29	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
    30	
    31	    public HttpTransLogClient(@Value("${translog.url}") String baseUrl, JsonMapper mapper) {
    32	        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    33	        this.mapper = mapper;
    34	    }
    35	
    36	    @Override
    37	    public Optional<TransLogQuote> quote(String zipCode, long weightGrams, String service) {
    38	        URI uri = URI.create(baseUrl + "/v2/quote?zip=" + encode(zipCode) + "&weight_g=" + weightGrams
    39	                + "&service=" + encode(service));
    40	        CompletableFuture<HttpResponse<String>> call = null;
    41	        try {
    42	            call = http.sendAsync(HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build(),
    43	                    HttpResponse.BodyHandlers.ofString());
    44	            HttpResponse<String> response = call.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    45	            if (response.statusCode() != 200) {
    46	                throw down();
    47	            }
    48	            return parse(mapper.readTree(response.body()));
    49	        } catch (InterruptedException e) {
    50	            Thread.currentThread().interrupt();
    51	            throw down();
    52	        } catch (DomainException e) {
    53	            throw e;
    54	        } catch (Exception e) {
    55	            if (call != null) {
    56	                call.cancel(true);
    57	            }
    58	            throw down();
    59	        }
    60	    }
    61	
    62	    private Optional<TransLogQuote> parse(JsonNode body) {
    63	        if (body.isObject() && "ZIP_NOT_SERVED".equals(body.path("error").asString(null))) {
    64	            return Optional.empty();
    65	        }
    66	        JsonNode price = body.path("price_cents");
    67	        JsonNode eta = body.path("eta_hours");
    68	        if (!price.isIntegralNumber() || !eta.isIntegralNumber() || !price.canConvertToInt()
    69	                || !eta.canConvertToInt() || price.asInt() < 0 || eta.asInt() < 0) {
    70	            throw down();
    71	        }
    72	        return Optional.of(new TransLogQuote(price.asInt(), eta.asInt()));
    73	    }
    74	
    75	    private static String encode(String value) {
    76	        return URLEncoder.encode(value, StandardCharsets.UTF_8);
    77	    }
    78	
    79	    private static DomainException down() {
    80	        return new DomainException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
    81	    }
    82	}
