    27	    @Override
    28	    public ShippingQuote quote(ShippingRequest request) {
    29	        long grams = request.weightKg().movePointRight(3).setScale(0, RoundingMode.CEILING).longValueExact();
    30	        TransLogClient.TransLogQuote quote = client.quote(request.zipCode(), grams, service)
    31	                .orElseThrow(() -> DomainException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
    32	        BigDecimal cost = Money.round(BigDecimal.valueOf(quote.priceCents(), 2));
    33	        int days = Math.ceilDiv(quote.etaHours(), 24) + request.region().carrierExtraDays();
    34	        return new ShippingQuote(cost, days);
