    19	
    20	/**
    21	 * Operações sobre pedidos. Cada uma trava o pedido, então operações simultâneas
    22	 * (inclusive vindas das duas máquinas) acontecem uma de cada vez.
    23	 * Recusas gravam seus efeitos (cancelamento, registro do aviso) e por isso não desfazem a transação.
    24	 */
    25	@Service
    26	@Transactional(noRollbackFor = DomainException.class)
    27	public class OrderService {
    28	
    29	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
    30	
    31	    private final CheckoutService checkout;
    32	    private final OrderRepository orders;
    33	    private final CustomerRepository customers;
    34	    private final StockService stock;
    35	    private final List<OrderEventListener> listeners;
    36	    private final Clock clock;
    37	
    38	    public OrderService(CheckoutService checkout, OrderRepository orders, CustomerRepository customers,
    39	                        StockService stock, List<OrderEventListener> listeners, Clock clock) {
    40	        this.checkout = checkout;
    41	        this.orders = orders;
    42	        this.customers = customers;
    43	        this.stock = stock;
    44	        this.listeners = listeners;
    45	        this.clock = clock;
    46	    }
    47	
    48	    public Order register(CheckoutRequest request) {
    49	        var summary = checkout.calculate(request);
    50	        customers.createIfAbsent(request.customer().cpf());
    51	        Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
    52	                Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, request.orderItems(), null,
    53	                request.customer().cpf(), request.customer().email());
    54	        orders.insert(order);
    55	        return order;
    56	    }
    57	
    58	    @Transactional(readOnly = true)
    59	    public Order get(String id) {
    60	        return orders.find(id).orElseThrow(OrderService::notFound);
    61	    }
    62	
    63	    public Order confirmPayment(String id, String transactionId, String paidAt) {
    64	        Order order = lock(id);
    65	        if (isBlank(transactionId) || isBlank(paidAt)) {
    66	            throw DomainException.unprocessable("INVALID_ORDER");
    67	        }
    68	        Instant paidInstant = parseInstant(paidAt);
    69	
    70	        var previous = orders.findPaymentNotice(id, transactionId);
    71	        if (previous.isPresent()) {
    72	            if (previous.get().isEmpty()) {
    73	                return order;
    74	            }
    75	            throw DomainException.conflict(previous.get());
    76	        }
    77	        if (!order.status().acceptsPayment()) {
    78	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
    79	        }
    80	        if (paidInstant.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
    81	            throw refuse(order, transactionId, "ORDER_EXPIRED");
    82	        }
    83	        try {
    84	            stock.reserve(order.items());
    85	        } catch (DomainException e) {
    86	            throw refuse(order, transactionId, e.code());
    87	        }
    88	        orders.update(id, OrderStatus.PAID, order.trackingCode());
    89	        Order paid = withStatus(order, OrderStatus.PAID, order.trackingCode());
    90	        listeners.forEach(listener -> listener.paymentConfirmed(paid));
    91	        orders.savePaymentNotice(id, transactionId, null);
    92	        return paid;
    93	    }
    94	
    95	    public Order ship(String id, String trackingCode) {
    96	        Order order = lock(id);
    97	        if (isBlank(trackingCode)) {
    98	            throw DomainException.unprocessable("INVALID_ORDER");
    99	        }
   100	        if (!order.status().canShip()) {
   101	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
   102	        }
   103	        orders.update(id, OrderStatus.SHIPPED, trackingCode);
   104	        Order shipped = withStatus(order, OrderStatus.SHIPPED, trackingCode);
   105	        listeners.forEach(listener -> listener.shipped(shipped));
   106	        return shipped;
   107	    }
   108	
   109	    public Order deliver(String id) {
   110	        Order order = lock(id);
   111	        if (!order.status().canDeliver()) {
   112	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
   113	        }
   114	        orders.update(id, OrderStatus.DELIVERED, order.trackingCode());
   115	        return withStatus(order, OrderStatus.DELIVERED, order.trackingCode());
   116	    }
   117	
   118	    public Order cancel(String id) {
   119	        Order order = lock(id);
   120	        if (!order.status().canCancel()) {
   121	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
   122	        }
   123	        return cancelLocked(order);
   124	    }
   125	
   126	    private DomainException refuse(Order order, String transactionId, String code) {
   127	        cancelLocked(order);
   128	        orders.savePaymentNotice(order.id(), transactionId, code);
   129	        return DomainException.conflict(code);
   130	    }
   131	
   132	    private Order cancelLocked(Order order) {
   133	        boolean wasPaid = order.status().paymentReceived();
   134	        orders.update(order.id(), OrderStatus.CANCELLED, order.trackingCode());
   135	        Order cancelled = withStatus(order, OrderStatus.CANCELLED, order.trackingCode());
   136	        if (wasPaid) {
   137	            stock.release(order.items());
   138	        }
   139	        listeners.forEach(listener -> listener.cancelled(cancelled, wasPaid));
   140	        return cancelled;
   141	    }
   142	
   143	    private Order lock(String id) {
   144	        return orders.findForUpdate(id).orElseThrow(OrderService::notFound);
   145	    }
   146	
   147	    private static Order withStatus(Order order, OrderStatus status, String trackingCode) {
   148	        return new Order(order.id(), status, order.createdAt(), order.summary(), order.items(), trackingCode,
   149	                order.cpf(), order.email());
   150	    }
   151	
   152	    private static Instant parseInstant(String value) {
   153	        try {
   154	            return Instant.parse(value);
   155	        } catch (DateTimeParseException e) {
   156	            throw DomainException.unprocessable("INVALID_ORDER");
   157	        }
   158	    }
   159	
   160	    private static boolean isBlank(String value) {
   161	        return value == null || value.isBlank();
   162	    }
   163	
   164	    private static DomainException notFound() {
   165	        return DomainException.notFound("ORDER_NOT_FOUND");
   166	    }
   167	}
