    10	import org.springframework.transaction.TransactionDefinition;
    11	import org.springframework.transaction.support.TransactionTemplate;
    12	
    13	import br.com.loja.pedidos.common.Money;
    14	
    15	@Repository
    16	public class CustomerRepository {
    17	
    18	    private final JdbcClient jdbc;
    19	    private final TransactionTemplate ownTransaction;
    20	
    21	    public CustomerRepository(JdbcClient jdbc, PlatformTransactionManager transactionManager) {
    22	        this.jdbc = jdbc;
    23	        this.ownTransaction = new TransactionTemplate(transactionManager);
    24	        this.ownTransaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    25	    }
    26	
    27	    /**
    28	     * Cria o cliente com saldo zero se ele ainda não existe. Roda em transação própria: se as duas máquinas
    29	     * tentarem criar o mesmo CPF juntas, a que perder só ignora o erro, sem estragar a transação do pedido.
    30	     */
    31	    public void createIfAbsent(String cpf) {
    32	        if (find(cpf).isPresent()) {
    33	            return;
    34	        }
    35	        try {
    36	            ownTransaction.executeWithoutResult(status ->
    37	                    jdbc.sql("INSERT INTO customers (cpf, credit_balance) VALUES (?, 0)").param(cpf).update());
    38	        } catch (DuplicateKeyException e) {
    39	            // outro pedido do mesmo CPF criou o cliente primeiro
    40	        }
    41	    }
    42	
    43	    public Optional<Customer> find(String cpf) {
    44	        return jdbc.sql("SELECT cpf, credit_balance FROM customers WHERE cpf = ?")
    45	                .param(cpf)
    46	                .query((rs, n) -> new Customer(rs.getString("cpf"), rs.getBigDecimal("credit_balance")))
    47	                .optional();
    48	    }
    49	
    50	    public void addCredit(String cpf, BigDecimal amount) {
    51	        jdbc.sql("UPDATE customers SET credit_balance = credit_balance + ? WHERE cpf = ?")
    52	                .param(Money.round(amount))
    53	                .param(cpf)
    54	                .update();
    55	    }
    56	}
