    11	/** Deve ser chamado dentro de uma transação. */
    12	@Service
    13	public class StockService {
    14	
    15	    private final ProductRepository products;
    16	
    17	    public StockService(ProductRepository products) {
    18	        this.products = products;
    19	    }
    20	
    21	    /** Baixa o estoque de todos os itens ou de nenhum; lança INSUFFICIENT_STOCK se algum faltar. */
    22	    public void reserve(List<OrderItem> items) {
    23	        // ordem fixa de SKU nas travas evita deadlock entre pagamentos simultâneos
    24	        List<OrderItem> sorted = items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
    25	        for (OrderItem item : sorted) {
    26	            int stock = products.lockStock(item.sku()).orElse(0);
    27	            if (stock < item.quantity()) {
    28	                throw DomainException.conflict("INSUFFICIENT_STOCK");
    29	            }
    30	        }
    31	        sorted.forEach(item -> products.addStock(item.sku(), -item.quantity()));
    32	    }
    33	
    34	    public void release(List<OrderItem> items) {
    35	        items.forEach(item -> products.addStock(item.sku(), item.quantity()));
    36	    }
    37	}
